-- ============================ PART 2: APPLY ================================
-- Only run this after you checked the rows from PART 1.
-- It runs as one all-or-nothing step: either every change happens, or none.

begin;

-- Test week · Grade 2
do $$ begin if not exists (select 1 from wp_classes where grade = 2) then
  raise exception 'No class for grade 2: import the roster first'; end if; end $$;
insert into wp_plans (title, kind) values ('Test week · Grade 2', 'test') on conflict (title) do update set kind = excluded.kind;
insert into wp_plan_assignments (plan_id, class_id)
  select (select id from wp_plans where title = 'Test week · Grade 2'), (select id from wp_classes where grade = 2 order by name, id limit 1) where not exists (select 1 from wp_plan_assignments where plan_id = (select id from wp_plans where title = 'Test week · Grade 2') and class_id = (select id from wp_classes where grade = 2 order by name, id limit 1));
insert into wp_weeks (plan_id, position, skill, opens_on) values ((select id from wp_plans where title = 'Test week · Grade 2'), 1, 'a / an / the and there is / are', '2026-11-26')
  on conflict (plan_id, position) do nothing;
insert into wp_lessons (week_id, position, title) values ((select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 2') and position = 1), 1, 'A or an?')
  on conflict (week_id, position) do nothing;
update wp_questions set type = 'pick_one', payload = '{"prompt":"Tap the sentence with no mistakes.","choices":["Otto found a ant in his bag.","Otto found an ant in his bag.","Otto found ant in his bag."],"answer":1,"picture":"ant"}'::jsonb, skill = 'articles', updated_at = now()
  where lesson_id = (select id from wp_lessons where week_id = (select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 2') and position = 1) and position = 1) and position = 1 and deleted_at is null
  and (type <> 'pick_one' or payload <> '{"prompt":"Tap the sentence with no mistakes.","choices":["Otto found a ant in his bag.","Otto found an ant in his bag.","Otto found ant in his bag."],"answer":1,"picture":"ant"}'::jsonb or skill is distinct from 'articles');
